"9-9": {
"l": 9,
"pg": 118,
"p": "何か／どこか・何も／どこへも〜ません",
"ex": "何か借りましたか。　はい、着物の本を借りました。　いいえ、何も借りませんでした。　昨日、どこかへ行きましたか。　はい、渋谷へ行きました。　いいえ、どこへも行きませんでした。　財布は（どこかに）ありましたか。　はい、うちにありました。　いいえ、どこにもありませんでした。",
"zh": "疑問詞＋か＝某個；疑問詞＋も＋否定＝都不～。",
"main": "A：何か借りましたか。 B：はい、着物の本を借りました。／いいえ、何も借りませんでした。",
"t": "A：何か借りましたか。 B：はい、着物の本を借りました。／いいえ、何も借りませんでした。（何か／どこか・何も／どこへも〜ません）"
},
"10-1": {
"l": 10,
"pg": 121,
"p": "Nに乗ります／Nを降ります／Nで行きます",
"ex": "新宿で電車に乗ります。　新宿から品川まで山手線で行きます。　新宿から品川まで電車で行きます。　私は毎日歩いて学校へ来ます。　新宿で山手線に乗ります。品川で電車を降ります。品川で新幹線に乗り換えます。　９時に新宿を出ます。９時２０分に品川に着きます。新宿から品川まで２０分かかります。",
"zh": "搭乘用「に乗る」、下車用「を降りる」、交通工具用「で」。",
"main": "新宿で電車に乗ります。",
"t": "新宿で電車に乗ります。（Nに乗ります／Nを降ります／Nで行きます）"
},
